function startRace(){clearPodium();if(chosenMode==='online'&&!launchingOnline){openOnlineLobby();return;}clearInput();helpState=null;recordWasBroken=false;if(chosenMode==='online'&&chosenMap===CUSTOM_ID){toast('Eigene Strecken gibt es bisher nur offline. Wähl für Online eine feste Strecke.');return;}if(chosenMode!=='online'&&chosenMap!==CUSTOM_ID&&!isArena(chosenMap)&&!unlockedMaps(profile).includes(chosenMap)){toast('Diese Strecke wird mit '+MAP_XP[chosenMap]+' XP freigeschaltet.');return;}if(!kartUnlocked(chosenKart)){chosenKart='allround';core.setKart(chosenKart);updatePlayerColor(chosenColor);}core.setWheels(myWheel());core.start(chosenMode==='online'?(activeMap.arena?'battle':'time'):chosenMode,chosenMap,{battle:activeMap.battle,items:chosenMode!=='time',cc:chosenMode==='online'?(onlineRace?.cc||80):chosenClass,kart:chosenKart});lastSlotState='';setupGhost();raceId=globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random();collectedCoins=0;finishAward=null;padCooldown=0;resetCoins();lastTick=4;goUntil=0;cameraMode=0;skidIndex=0;skidMesh.count=0;createGridPreview();rivalCars.forEach((car,i)=>car.visible=chosenMode==='race'||chosenMode==='battle');document.querySelector('.lap-box small').textContent=core.mode==='battle'?{balloons:'BALLONS',coins:'MÜNZEN',crown:'KRONE'}[activeMap.battle]:'RUNDE';document.querySelector('#mapHud>small').textContent=core.mode==='battle'?{balloons:'BALLON-BATTLE · 2:30',coins:'MÜNZJAGD · 2:00',crown:'KRONENJAGD · 20 S HALTEN'}[activeMap.battle]:chosenMode==='time'?'3 RUNDEN · ZEITFAHREN':cupRun?`${cupById(cupRun.id).name.toUpperCase()} · RENNEN ${cupRun.idx+1} / 3`:'3 RUNDEN · GRAND PRIX';document.querySelector('.time-box small').textContent=core.mode==='battle'?'RESTZEIT':'RENNZEIT';$('menuLayer').hidden=true;$('locationTag')?.setAttribute('hidden','');$('pause').textContent='Ⅱ';setRaceHud(true);const p=core.player;camYaw=p.angle;camera.position.set(p.x-Math.sin(p.angle)*4.4,p.y+2.6,p.z-Math.cos(p.angle)*4.4);lastLook.set(p.x+Math.sin(p.angle)*3,p.y+.65,p.z+Math.cos(p.angle)*3);renderer.domElement.focus({preventScroll:true});audio.bleep('click');updateHud();}
