// Danger from behind (rocket, red shell aimed at me, star) as a small icon with "!" next to my kart.
const threatV=new THREE.Vector3();let lastThreat='';
function updateThreats(){
  const el=$('threatHud');if(!['racing'].includes(core.status)||cameraMode===1){if(!el.hidden)el.hidden=true;return;}
  const L=core.track.length,me=core.playerProgress,list=new Set();
  const behind=(prog,m)=>{const d=(me-prog)*L;return d>-2&&d<m;};
  for(const b of core.rivals){if(b.rocketT>0&&behind(b.progress,170))list.add('rocket');if(b.starT>0&&behind(b.progress,45))list.add('star');}
  for(const sh of core.shells){if(sh.type==='red'&&sh.target===core.player&&sh.owner!==core.player)list.add('red');if(sh.type==='blue'&&sh.target===core.player&&!(sh.boom>0))list.add('blue');}
  if(onlineRace){for(const e of remoteCars.values()){const t=e.target;if(t.rocket&&behind(t.progress??0,170))list.add('rocket');else if(t.star&&behind(t.progress??0,45))list.add('star');}
    for(const e of onlineBots.values()){const t=e.target;if(t.rocket&&behind(t.progress??0,170))list.add('rocket');else if(t.star&&behind(t.progress??0,45))list.add('star');}
    for(const it of core.externalItems){if(it.type==='red'&&Math.hypot(it.x-core.player.x,it.z-core.player.z)<30)list.add('red');if(it.type==='blue'&&!it.b&&onlineFieldRank().rank===1)list.add('blue');}}
  const key=[...list].join(',');if(!key){if(!el.hidden)el.hidden=true;lastThreat='';return;}
  if(key!==lastThreat){el.innerHTML=[...list].map(k=>`<i>${ITEM_SVG[k]}<b>!</b></i>`).join('');lastThreat=key;audio.bleep('tick');}
  threatV.copy(playerCar.position);threatV.y+=1.1;threatV.project(camera);
  el.style.left=((threatV.x*.5+.5)*innerWidth+86)+'px';el.style.top=((-threatV.y*.5+.5)*innerHeight)+'px';el.hidden=false;
}
