// Dead reckoning: extrapolate along the last known velocity, then glide toward it.
function smoothEntry(entry,dt){
  const t=entry.target,ang=t.angle??t.a??0,spd=t.speed??t.s??0,vx=t.vx??Math.sin(ang)*spd,vz=t.vz??Math.cos(ang)*spd;
  const age=Math.min(.4,(performance.now()-entry.received)/1000),px=t.x+vx*age,pz=t.z+vz*age;
  const ty=t.y??0;entry.ry=entry.ry===undefined?ty:entry.ry+(ty-entry.ry)*(1-Math.exp(-dt*12));entry.pitch=(entry.pitch||0)+((t.pitch??t.pi??0)-(entry.pitch||0))*(1-Math.exp(-dt*10));
  if(entry.rx===undefined||Math.hypot(px-entry.rx,pz-entry.rz)>14){entry.rx=px;entry.rz=pz;entry.yaw=ang;entry.ry=ty;}
  else{entry.rx+=vx*dt;entry.rz+=vz*dt;const k=1-Math.exp(-dt*7);entry.rx+=(px-entry.rx)*k;entry.rz+=(pz-entry.rz)*k;
    entry.yaw+=Math.atan2(Math.sin(ang-entry.yaw),Math.cos(ang-entry.yaw))*(1-Math.exp(-dt*12));}
  return {vx,vz};
}
function onlineFieldList(){
  const humans=sortedOnlinePlayers().map(p=>({id:p.id,name:p.name,color:p.color,progress:p.id===network.state.selfId?core.playerProgress:p.progress,finished:p.finishedTime!==null,dnf:p.dnf,self:p.id===network.state.selfId}));
  const bots=core.keepBotsRacing?core.rivals.map(b=>({name:b.name,color:'#'+b.color.toString(16).padStart(6,'0'),progress:b.progress,bot:true}))
    :[...onlineBots.values()].map(e=>({name:RIVAL_ROSTER[e.n].name,color:'#'+RIVAL_ROSTER[e.n].color.toString(16).padStart(6,'0'),progress:e.target.progress??e.target.p??0,bot:true}));
  return [...humans,...bots].sort((a,b)=>(b.finished-a.finished)||(b.progress-a.progress));
}
