let sunOffset=new THREE.Vector3(70,120,45);
function themeSurroundings(){
  const L=THEME_LOOK[activeMap.theme]||THEME_LOOK.day,u=sky.material.uniforms;
  u.top.value.set(L.top);u.horizon.value.set(L.horizon);u.ground.value.set(L.ground);u.glow.value.set(L.glow);
  u.sunColor.value.set(L.sunColor).multiplyScalar(L.sunI);u.stars.value=L.stars;
  sunOffset.set(...L.sunOff);u.sunDir.value.copy(sunOffset).normalize();
  scene.fog.color.set(L.fog);scene.fog.near=L.near;scene.fog.far=L.far;scene.background.set(L.fog);
  envDirty=true;
}
// Echte Reflexionen: die Halle selbst wird einmal in eine Cubemap gerendert und als Umgebung genutzt.
function bakeEnvironment(){
  if(!envDirty)return;envDirty=false;
  const hidden=[];scene.traverse(o=>{if(o.isGroup&&o.name.startsWith('Mini Formula')&&o.visible){o.visible=false;hidden.push(o);}});
  const cubeRT=new THREE.WebGLCubeRenderTarget(256,{type:THREE.HalfFloatType,generateMipmaps:false});
  const cubeCam=new THREE.CubeCamera(.5,1500,cubeRT);cubeCam.position.copy(decorGroup?.userData.envPosition||new THREE.Vector3(0,6,0));scene.add(cubeCam);
  const prevEnv=scene.environment;scene.environment=null;cubeCam.update(renderer,scene);scene.remove(cubeCam);
  pmrem??=new THREE.PMREMGenerator(renderer);
  const next=pmrem.fromCubemap(cubeRT.texture);cubeRT.dispose();
  hidden.forEach(o=>o.visible=true);
  envRT?.dispose();envRT=next;scene.environment=next.texture;
}
function buildComposer(){
  composer=null;gtaoPass=null;bloomPass=null;
  renderer.setPixelRatio(1);renderer.setSize(innerWidth,innerHeight);
  if(sun.shadow.mapSize.x!==2048){sun.shadow.mapSize.set(2048,2048);sun.shadow.map?.dispose();sun.shadow.map=null;}
}
function renderFrame(dt){if(garageOpen&&garage){garage.update(dt,performance.now()/1000);renderer.render(garage.scene,garage.camera);return;}bakeEnvironment();if(sky)sky.position.copy(camera.position);if(composer)composer.render(dt);else renderer.render(scene,camera);}
