// ===================== Siegerehrung =====================
let victory=null;
function startVictory(sub,then,{title='SIEG!',car=true,hold=3.6}={}){
  const el=$('victory'),cv=$('confetti');$('victorySub').textContent=sub;el.querySelector('.victory-title').textContent=title;el.classList.toggle('top',!car);el.classList.remove('out');el.hidden=false;
  cv.width=innerWidth;cv.height=innerHeight;
  const colors=['#ffd04a','#ff653d','#f5f5f0','#d9f28a',chosenColor],pieces=[];
  for(let i=0;i<170;i++){const side=i%2?1:-1;pieces.push({x:side>0?cv.width+10:-10,y:cv.height*(.55+Math.random()*.35),vx:-side*(5+Math.random()*9)*cv.width/1200,vy:-(9+Math.random()*9)*cv.height/800,r:Math.random()*6,vr:(Math.random()-.5)*.4,w:6+Math.random()*7,h:3+Math.random()*4,c:colors[i%colors.length],delay:Math.random()*.5});}
  victory={t:0,then,shown:false,pieces,spin:0,hop:0,car,hold};
  el.onclick=()=>{if(victory&&!victory.shown)victory.t=Math.max(victory.t,3.4);};
}
function endVictory(){victory=null;const el=$('victory');el.hidden=true;el.classList.remove('out');}
function updateVictory(dt){
  if(!victory)return;
  if(core.status!=='finished'){endVictory();return;}
  const v=victory;v.t+=dt;
  // Car: a hop, then a fast 360° donut that eases out.
  if(v.car){const k=Math.min(1,Math.max(0,(v.t-.5)/1.6));v.spin=(1-Math.pow(1-k,3))*Math.PI*2;
  v.hop=v.t>.35&&v.t<.95?Math.sin((v.t-.35)/.6*Math.PI)*.55:0;
  if(v.t>.5&&v.t<2.1&&Math.random()<dt*14)spark(core.player.x,core.player.z,3);}
  // Confetti on a 2D canvas: two cannons from the sides, gravity and flutter.
  const cv=$('confetti'),g=cv.getContext('2d');g.clearRect(0,0,cv.width,cv.height);
  for(const p of v.pieces){if(v.t<p.delay)continue;p.vy+=.35*dt*60*cv.height/800;p.vx*=Math.pow(.985,dt*60);p.vy=Math.min(p.vy,3.2*cv.height/800);p.x+=p.vx*dt*60;p.y+=p.vy*dt*60;p.r+=p.vr*dt*60;
    g.save();g.translate(p.x,p.y);g.rotate(p.r);g.scale(1,Math.cos(p.r*1.7));g.fillStyle=p.c;g.fillRect(-p.w/2,-p.h/2,p.w,p.h);g.restore();}
  if(v.t>v.hold&&!v.shown){v.shown=true;$('victory').classList.add('out');v.then();}
  if(v.t>v.hold+.6)$('victory').hidden=true;
}
