let battleReturnMap=null;
const balloonGeo=new THREE.SphereGeometry(.16,14,10);
// Balloons ride behind the driver's head; the group is made once per car model.
function syncBalloons(car,count,color,t){
  let g=car.userData.balloonGroup;
  if(!g){if(!count)return;g=new THREE.Group();g.userData.items=[];for(let i=0;i<MAX_BALLOONS;i++){const b=new THREE.Mesh(balloonGeo,new THREE.MeshStandardMaterial({color,roughness:.3,emissive:color,emissiveIntensity:.25}));b.scale.y=1.25;g.add(b);g.userData.items.push(b);}car.add(g);car.userData.balloonGroup=g;}
  g.visible=count>0;if(!count)return;
  g.userData.items.forEach((b,i)=>{b.visible=i<count;const a=(i-(count-1)/2)*.6;b.position.set(Math.sin(a)*.3,.98+Math.sin(t*2.2+i*1.7)*.05-Math.abs(a)*.08,-.68+Math.cos(a)*.05);});
}
