function menuNav(b){
  if(onlineLobbyOpen)return false;
  if(b.dataset.play){playStyle=b.dataset.play;menuStep=b.dataset.jump||(playStyle==='online'?'driver':'mode');renderGarage();audio.bleep('click');return true;}
  if(b.dataset.pickmode){const m=b.dataset.pickmode;menuTab=m;chosenMode=m==='cup'?'race':m;if(m!=='battle'&&isArena(chosenMap))selectMap(battleReturnMap||'coast');menuStep='driver';renderGarage();audio.bleep('click');return true;}
  if(b.dataset.avatar){const id=b.dataset.avatar,av=avatarById(id);if(!avatarOk(id)){toast(av.name.toUpperCase()+' · '+avatarNeed(av),3600);return true;}chosenAvatar=id;try{localStorage.setItem('apex-rush-avatar',id);}catch{}updatePlayerColor(chosenColor);renderGarage();audio.bleep('click');return true;}
  if(b.dataset.cc&&menuStep==='class'){chosenClass=+b.dataset.cc;try{localStorage.setItem('apex-rush-cc',String(chosenClass));}catch{}menuStep='track';renderGarage();audio.bleep('click');return true;}
  if(b.dataset.step){const order=stepOrder(),i=order.indexOf(menuStep);let s=b.dataset.step;
    if(s==='back')s=order[Math.max(0,i-1)];else if(s==='next'){if(playStyle==='online'&&menuStep==='driver'){openOnlineLobby();return true;}s=order[Math.min(order.length-1,i+1)];}
    if(!order.includes(s))return true;menuStep=s;renderGarage();audio.bleep('click');return true;}
  return false;
}
const COLORS=[['#ee4b37','RACING RED'],['#42c9cb','TURBO TÜRKIS'],['#edc44b','GOLDEN ENGINEER'],['#9b87e5','PURPLE PROTOTYPE'],['#3fbf5a','JUNGLE GREEN'],['#f2f2ea','ARCTIC WHITE'],['#2b2f38','CARBON BLACK'],['#ff7ac2','PINK PULSE']];
// Stats as 0…100 % for the garage bars.
function kartPct(k){const f=(v,lo,hi)=>Math.round(Math.max(.08,Math.min(1,(v-lo)/(hi-lo)))*100);return [['TEMPO',f(k.top,.94,1.04)],['BESCHLEUNIGUNG',f(k.accel,.7,1.4)],['HANDLING',f(2-k.turn,2-1.5,2-.5)],['GEWICHT',f(k.mass,.7,1.8)],['DRIFT',f(k.drift,.85,1.45)],['OFFROAD',f(k.offroad,.28,.85)]];}
function garageCard(){const k=kartById(chosenKart),col=COLORS.find(c=>c[0]===chosenColor)?.[1]||'';return `<div class="garage-card"><div class="gc-top"><i style="background:${chosenColor}"></i><div><small>DEIN FAHRZEUG</small><b>${k.name}</b><span>${k.tag} · ${col}</span></div></div><div class="kart-stats">${kartStats(k).map(([n,v])=>`<span><small>${n}</small><i>${'<em></em>'.repeat(v)}${'<u></u>'.repeat(5-v)}</i></span>`).join('')}</div><button class="garage-open" data-garage="open">🔧 ZUR GARAGE <small>Fahrzeug & Lackierung wählen</small></button></div>`;}
// ===================== 3D garage =====================
let garage=null,garageOpen=false,garageIndex=0;
function garageModel(){garage.setCar(createCar(chosenColor,'07',KARTS[garageIndex].id,myFinish(),mySkin(),myAvatar(),myWheel()));}
function openGarage(){garage??=createGarage();garageIndex=Math.max(0,KARTS.findIndex(k=>k.id===chosenKart));garageModel();garageOpen=true;$('menuLayer').hidden=true;document.querySelector('header').classList.add('in-garage');let ui=$('garageUi');if(!ui){ui=document.createElement('div');ui.id='garageUi';ui.className='garage-ui';document.body.appendChild(ui);ui.addEventListener('click',onGarageClick);}ui.hidden=false;renderGarageUi();audio.bleep('click');}
function closeGarage(){garageOpen=false;$('garageUi').hidden=true;document.querySelector('header').classList.remove('in-garage');$('menuLayer').hidden=false;if(onlineLobbyOpen)renderOnlineLobby(true);else renderGarage();}
function renderGarageUi(){const k=KARTS[garageIndex],sel=k.id===chosenKart,locked=!kartUnlocked(k.id);$('garageUi').innerHTML=`<div class="g-panel"><div class="menu-kicker"><i></i> APEX GARAGE · FAHRZEUG ${garageIndex+1} / ${KARTS.length}</div><h1>${k.name}</h1><div class="g-tag">${k.tag}${sel?' <b>✓ IM EINSATZ</b>':''}${locked?' <b class="g-lock">🔒 AB LEVEL '+KART_LEVEL[k.id]+'</b>':''}</div><p>${k.desc}</p><div class="g-stats">${kartPct(withWheels(k,myWheel())).map(([n,v])=>`<div><small>${n}</small><span><i style="width:${v}%"></i></span><b>${Math.round(v/10)}</b></div>`).join('')}</div><div class="g-colors"><small>LACKIERUNG</small><div>${COLORS.map(([c,name])=>`<button class="g-swatch${c===chosenColor?' selected':''}" data-gcolor="${c}" style="--swatch:${c}" title="${name}" aria-label="${name}"></button>`).join('')}</div></div><div class="g-colors g-finishes"><small>LACK-FINISH</small><div>${FINISHES.map(f=>`<button class="g-finish${f.id===chosenFinish?' selected':''}${finishUnlocked(f.id)?'':' locked'}" data-gfinish="${f.id}">${finishUnlocked(f.id)?f.name:'🔒 LV '+f.level}</button>`).join('')}</div></div><div class="g-wheels"><small>RÄDER <b>${wheelById(myWheel()).name.toUpperCase()}</b></small><div>${WHEELS.map(w=>{const ok=wheelOk(w.id),m=w.mod,tags=[['top','TEMPO'],['accel','BESCHL.'],['drift','DRIFT'],['turn','HANDLING',true],['mass','GEWICHT']].filter(([f])=>m[f]&&m[f]!==1).map(([f,n,inv])=>{const up=inv?m[f]<1:m[f]>1;return `<i class="${up?'up':'down'}">${up?'▲':'▼'} ${n}</i>`;}).concat(m.offroad?[`<i class="${m.offroad>0?'up':'down'}">${m.offroad>0?'▲':'▼'} OFFROAD</i>`]:[]).join('');return `<button class="g-wheel${w.id===myWheel()?' selected':''}${ok?'':' locked'}" data-gwheel="${w.id}" title="${w.desc}">${wheelIcon(w)}<b>${w.name}</b><small>${ok?w.tag:'🔒 LEVEL '+w.level}</small><span>${tags||'<i>AUSGEWOGEN</i>'}</span></button>`;}).join('')}</div></div><div class="g-skins"><small>SKINS <b>${SKINS.filter(x=>skinOk(x.id)).length} / ${SKINS.length}</b></small><div>${SKINS.map(x=>{const ok=skinOk(x.id);return `<button class="g-skin${x.id===mySkin()?' selected':''}${ok?'':' locked'} r-${x.rarity.replace(/[^a-z]/g,'')}" data-gskin="${x.id}" title="${x.name} · ${ok?x.rarity:skinRequirement(x)}"><span style="${x.id==='none'?'background:'+chosenColor:`background-image:url(${skinPreview(x.id,chosenColor)})`}"></span><b>${x.name}</b><small>${ok?x.rarity:'🔒 '+skinRequirement(x)}</small></button>`;}).join('')}</div></div><div class="g-actions"><button class="primary" data-g="select" ${locked?'disabled':''}>${locked?'GESPERRT · LEVEL '+KART_LEVEL[k.id]:sel?'WEITER MIT DIESEM KART':'DIESES KART NEHMEN'} <span>${locked?'⌑':'↗'}</span></button><button class="secondary" data-g="back">${onlineLobbyOpen?'Zurück zur Lobby':'Zurück zum Menü'}</button></div></div><button class="g-arrow left" data-g="prev" aria-label="Vorheriges Kart">‹</button><button class="g-arrow right" data-g="next" aria-label="Nächstes Kart">›</button><div class="g-dots">${KARTS.map((x,i)=>`<i class="${i===garageIndex?'on':''}"></i>`).join('')}</div><div class="g-hint">Ziehen zum Drehen · ← → blättern · Enter wählen</div>`;}
// Small wheel picture for the garage cards (tyre, rim colour, studs).
function wheelIcon(w){const L=w.look,rim=L.rim==='paint'?chosenColor:L.rim,r=18*Math.min(1.2,L.r);const studs=L.knob?Array.from({length:12},(_,i)=>{const a=i/12*Math.PI*2;return `<rect x="${(24+Math.cos(a)*(r+1)-2.5).toFixed(1)}" y="${(24+Math.sin(a)*(r+1)-2.5).toFixed(1)}" width="5" height="5" rx="1" fill="#1a1c20"/>`;}).join(''):'';const sp=Array.from({length:L.spokes||5},(_,i)=>{const a=i/(L.spokes||5)*Math.PI*2;return `<line x1="24" y1="24" x2="${(24+Math.cos(a)*r*.55).toFixed(1)}" y2="${(24+Math.sin(a)*r*.55).toFixed(1)}" stroke="#f4f4f0" stroke-width="2"/>`;}).join('');return `<svg viewBox="0 0 48 48">${studs}<circle cx="24" cy="24" r="${r}" fill="#22252b"/><circle cx="24" cy="24" r="${(r*.62).toFixed(1)}" fill="${rim}"/>${L.band?`<circle cx="24" cy="24" r="${(r*.8).toFixed(1)}" fill="none" stroke="${L.band}" stroke-width="1.5"/>`:''}${sp}<circle cx="24" cy="24" r="3" fill="#dfe5ea"/></svg>`;}
function garageStep(d){garageIndex=(garageIndex+d+KARTS.length)%KARTS.length;garageModel();renderGarageUi();audio.bleep('tick');}
function garageSelect(){if(!kartUnlocked(KARTS[garageIndex].id)){toast(KARTS[garageIndex].name+' wird mit Level '+KART_LEVEL[KARTS[garageIndex].id]+' freigeschaltet.');return;}chosenKart=KARTS[garageIndex].id;try{localStorage.setItem('apex-rush-kart',chosenKart);}catch{}core.setKart(chosenKart);updatePlayerColor(chosenColor);audio.bleep('lap');closeGarage();}
function onGarageClick(e){const b=e.target.closest('button');if(!b)return;if(b.dataset.gwheel){const w=wheelById(b.dataset.gwheel);if(!wheelOk(w.id)){toast(w.name+' wird mit Level '+w.level+' freigeschaltet.');return;}chosenWheel=w.id;try{localStorage.setItem('apex-rush-wheel',chosenWheel);}catch{}updatePlayerColor(chosenColor);garageModel();renderGarageUi();audio.bleep('click');return;}if(b.dataset.gskin){const x=skinById(b.dataset.gskin);if(!skinOk(x.id)){toast('🔒 '+x.name+': '+skinRequirement(x),2600);return;}chosenSkin=x.id;try{localStorage.setItem('apex-rush-skin',chosenSkin);}catch{}updatePlayerColor(chosenColor);garageModel();renderGarageUi();audio.bleep('click');return;}if(b.dataset.gfinish){const f=FINISHES.find(x=>x.id===b.dataset.gfinish);if(!finishUnlocked(f.id)){toast('Lack '+f.name+' wird mit Level '+f.level+' freigeschaltet.');return;}chosenFinish=f.id;try{localStorage.setItem('apex-rush-finish',chosenFinish);}catch{}updatePlayerColor(chosenColor);garageModel();renderGarageUi();audio.bleep('click');return;}if(b.dataset.gcolor){chosenColor=b.dataset.gcolor;try{localStorage.setItem('apex-rush-color',chosenColor);}catch{}updatePlayerColor(chosenColor);garageModel();renderGarageUi();return;}const a=b.dataset.g;if(a==='prev')garageStep(-1);if(a==='next')garageStep(1);if(a==='select')garageSelect();if(a==='back'){audio.bleep('click');closeGarage();}}
function kartPicker(){const k=kartById(chosenKart);return `<div class="choose-kart"><label>DEIN FAHRZEUG <b>${k.name.toUpperCase()} · ${k.tag}</b></label><div class="kart-buttons">${KARTS.map(x=>`<button class="kart-btn${x.id===chosenKart?' selected':''}${kartUnlocked(x.id)?'':' locked'}" data-kart="${x.id}" aria-pressed="${x.id===chosenKart}"><b>${x.name}</b><small>${kartUnlocked(x.id)?x.tag:'🔒 LEVEL '+KART_LEVEL[x.id]}</small></button>`).join('')}</div><div class="kart-stats">${kartStats(k).map(([n,v])=>`<span><small>${n}</small><i>${'<em></em>'.repeat(v)}${'<u></u>'.repeat(5-v)}</i></span>`).join('')}</div><p class="kart-desc">${k.desc}</p></div>`;}
function stylePoints(){return collectedCoins*25+Math.floor(Math.min(8,core.stats?.driftSeconds||0)*25);}
function setupCoins(){coinGroup=new THREE.Group();coins=[];const ringGeo=new THREE.TorusGeometry(.23,.055,6,16),chipGeo=new THREE.CylinderGeometry(.16,.16,.055,6),glowGeo=new THREE.CircleGeometry(.29,18),gold=new THREE.MeshStandardMaterial({color:0xf4cb55,metalness:.65,roughness:.25,emissive:0x976322,emissiveIntensity:.2}),inner=new THREE.MeshStandardMaterial({color:0xfff1a8,metalness:.45,roughness:.3}),glowMat=new THREE.MeshBasicMaterial({color:0xf3cb64,transparent:true,opacity:.22,side:THREE.DoubleSide,depthWrite:false});for(let i=0;i<12;i++){const s=sampleTrack((.055+i/12)%1),lane=i%3===0?-1.5:i%3===1?1.5:0,x=s.x+s.nx*lane,z=s.z+s.nz*lane,g=new THREE.Group();g.position.set(x,s.y+.72,z);const ring=new THREE.Mesh(ringGeo,gold),disc=new THREE.Mesh(chipGeo,inner);disc.rotation.x=Math.PI/2;g.add(ring,disc);const glow=new THREE.Mesh(glowGeo,glowMat);glow.rotation.x=-Math.PI/2;glow.position.set(x,s.y+.023,z);coinGroup.add(g,glow);coins.push({x,z,y:s.y,mesh:g,glow,taken:false,index:i});}scene.add(coinGroup);}
function resetCoins(){for(const c of coins){c.taken=false;c.mesh.visible=true;c.glow.visible=true;}}
function updateCoins(dt){for(const c of coins){if(c.taken)continue;c.mesh.rotation.y+=dt*1.8;c.mesh.position.y=c.y+.72+Math.sin(core.elapsed*3+c.index)*.06;if(Math.hypot(core.player.x-c.x,core.player.z-c.z)<.92&&Math.abs(core.player.y-c.y)<2){c.taken=true;c.mesh.visible=false;c.glow.visible=false;collectedCoins++;audio.bleep('coin');$('pointsHud').classList.remove('collected');void $('pointsHud').offsetWidth;$('pointsHud').classList.add('collected');}}}

function escapeText(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function getNickname(){const field=$('onlineName');nickname=(field?.value||nickname).trim().slice(0,20)||'Rookie Pilot';try{localStorage.setItem('apex-rush-name',nickname);}catch{}return nickname;}
