  if($('lobbyReadyCount'))$('lobbyReadyCount').textContent=ready+' VON '+total+' BEREIT';
  if($('lobbyReadyBar'))$('lobbyReadyBar').style.width=(total?ready/total*100:0)+'%';
  if($('onlineRoster')){const bots=host&&wantsOnlineBots(),slots=Math.max(4,total+(total%2));
    $('onlineRoster').innerHTML=state.players.map((p,i)=>{const lk=p.look||{},a=avatarById(lk.avatar||'pilot'),k=kartById(lk.kart||'allround'),me=p.id===state.selfId,st=!p.connected?'left':p.ready?'ready':'waiting';
      return `<div class="lb-card ${st} ${me?'me':''}" style="--pc:${p.color}"><span class="lb-pos">${i+1}</span><div class="lb-por">${avatarPortrait(a.id)}</div><div class="lb-info"><b>${escapeText(p.name)}${p.id===state.hostId?' <em title="Gastgeber">👑</em>':''}${me?' <u>DU</u>':''}</b><small>${k.name} · ${a.name}</small></div><span class="lb-state">${st==='left'?'VERBINDET …':st==='ready'?'✓ BEREIT':'WARTET'}</span></div>`;}).join('')
      +Array.from({length:Math.max(0,slots-total)},(_,i)=>`<div class="lb-card empty"><span class="lb-pos">${total+i+1}</span><div class="lb-por"></div><div class="lb-info"><b>${bots?'KI-Fahrer':'Freier Platz'}</b><small>${bots?'füllt beim Start auf':'Code teilen zum Einladen'}</small></div></div>`).join('');}
  const mk=state.mapId+'|'+state.role+'|'+state.status;
  if($('onlineMapPicker')&&lobbyMapKey!==mk){lobbyMapKey=mk;const m=[...MAPS,...ARENAS].find(x=>x.id===state.mapId)||MAPS[0];
    $('onlineMapPicker').innerHTML=host?[...MAPS,...ARENAS].map(x=>`<button class="lb-map ${state.mapId===x.id?'on':''} ${x.arena?'arena':''}" data-online="map" data-map-id="${x.id}" ${state.status!=='lobby'?'disabled':''}>${mapSvg(x)}<b>${x.arena?BATTLE_INFO[x.battle].icon+' ':''}${x.name}</b>${x.arena?`<small>${BATTLE_INFO[x.battle].title}</small>`:''}</button>`).join('')
      :`<div class="lb-map big on">${mapSvg(m)}<b>${m.name}</b><small>${THEME_LABEL[m.theme]||''}</small></div>`;
    if($('lobbyMapName'))$('lobbyMapName').textContent=m.name.toUpperCase();
    if(host)requestAnimationFrame(()=>$('onlineMapPicker')?.querySelector('.on')?.scrollIntoView({block:'nearest'}));}
  if($('onlineReady')){const on=!!self?.ready;$('onlineReady').classList.toggle('on',on);$('onlineReady').disabled=state.status!=='lobby'||!self?.connected;$('onlineReadyText').textContent=on?'DU BIST BEREIT':'BEREIT?';}
  if($('onlineGuestWait'))$('onlineGuestWait').textContent=state.status==='connecting'?'Verbindung wird hergestellt …':state.status==='results'?'Der Gastgeber bereitet die nächste Runde vor.':self?.ready?(host?'Klicke nochmal, um es zurückzunehmen':'Warte auf den Start · nochmal klicken zum Zurücknehmen'):'Hier klicken (oder Taste R), wenn du startklar bist';
  if($('onlineStart')){const can=network.canStart&&!lobbyBusy;$('onlineStart').disabled=!can;$('onlineStart').classList.toggle('go',can);$('onlineStart').innerHTML=can?'<b>'+([...ARENAS].some(a=>a.id===state.mapId)?'BATTLE STARTEN':'RENNEN STARTEN')+'</b><small>Alle sind bereit · los geht\'s!</small>':total<2?'<b>WARTE AUF FREUNDE</b><small>Mindestens 2 Fahrer nötig</small>':`<b>NOCH ${total-ready} NICHT BEREIT</b><small>Alle müssen auf BEREIT klicken</small>`;}
