  const ext=[];
  for(const [rid,entry] of remoteCars){const t=entry.target,v=smoothEntry(entry,dt);glideAnim(entry.car,!!t.glide);if((t.kart&&entry.car.userData.kart!==t.kart)||(t.skin||'none')!==entry.car.userData.skin||(t.avatar||'pilot')!==entry.car.userData.avatar||(t.wheel||'standard')!==entry.car.userData.wheel){const old=entry.car,tag=old.children.find(o=>o.isSprite);entry.car=createCar(entry.color,old.name.slice(-2),t.kart||'allround',t.finish||'standard',t.skin||'none',t.avatar||'pilot',t.wheel||'standard');if(tag){old.remove(tag);entry.car.add(tag);}scene.add(entry.car);destroyCar(old);}entry.car.position.set(entry.rx,entry.ry,entry.rz);entry.car.rotation.y=entry.yaw+(t.spinA||0);entry.car.rotation.x=-(entry.pitch||0);ext.push({key:'p:'+rid,x:entry.rx,z:entry.rz,y:entry.ry,mass:t.mass||1,trail:t.trail||null,progress:t.progress,speed:t.speed,angle:entry.yaw,vx:v.vx,vz:v.vz,name:entry.name,star:!!t.star,ghost:performance.now()-entry.received>1500});entry.car.visible=true;rocketVisual('o'+entry.name,entry.car,t.rocket?{x:entry.car.position.x,z:entry.car.position.z,y:entry.ry,angle:entry.yaw,rocketT:1}:null,performance.now());rescueFx?.update('o'+entry.name,t.fallT>0?{x:entry.rx,y:entry.ry,z:entry.rz,angle:entry.yaw,fallT:t.fallT}:null,ms,dt);itemFx?.bubble('o'+entry.name,t.bubble?{x:entry.rx,y:entry.ry,z:entry.rz,angle:entry.yaw,bubble:true}:null,ms);starPaint(entry.car,!!t.star,performance.now());animateCar(entry.car,t,dt);}
